// 스레드에 가까운 것 — 메모리를 함께 쓰지 않는다는 점이 다르다
const w = new Worker('worker.js');
w.postMessage(data);            // 값을 복사해 보낸다(구조화 복제)

// 진짜로 메모리를 함께 쓰려면
const buf = new SharedArrayBuffer(1024);
const view = new Int32Array(buf);
Atomics.add(view, 0, 1);        // 동시에 건드려도 안전한 연산

const n = navigator.hardwareConcurrency || 4;   // 브라우저
const pool = Array.from({ length: n }, () => new Worker('w.js'));

// Node
import os from 'node:os';
const n2 = os.cpus().length;

// 기다리는 느림 — 동시에 보내면 된다
const [a, b] = await Promise.all([fetch(u1), fetch(u2)]);

// 계산하는 느림 — 다른 줄기로 넘긴다
const worker = new Worker('heavy.js');
worker.postMessage(input);
worker.onmessage = (e) => render(e.data);

let shuttingDown = false;
for (const sig of ['SIGTERM', 'SIGINT']) {
  process.on(sig, async () => {
    if (shuttingDown) return;      // 두 번 눌러도 한 번만
    shuttingDown = true;
    server.close();                // 새 연결은 안 받고
    await drainInFlight();         // 하던 요청은 마치고
    await db.close();
    process.exit(0);
  });
}
